"use client"

import type React from "react"

import { useState, useRef, useEffect } from "react"
import { Input } from "@/components/ui/input"
import { Search, MapPin, Clock, TrendingUp } from "lucide-react"
import { cn } from "@/lib/utils"

interface SearchSuggestion {
  id: string
  name: string
  type: "destination" | "food" | "event" | "hotel"
  location?: string
}

const recentSearches = ["Tokyo, Japan", "Italian restaurants", "Beach resorts"]

const trendingSearches = ["Maldives", "Northern Lights", "Safari tours", "Ski resorts"]

const suggestions: SearchSuggestion[] = [
  { id: "1", name: "Paris, France", type: "destination", location: "Europe" },
  { id: "2", name: "Parisian Bistro", type: "food", location: "New York" },
  { id: "3", name: "Paris Fashion Week", type: "event", location: "Paris, France" },
  { id: "4", name: "Park Hyatt Paris", type: "hotel", location: "Paris, France" },
]

interface SearchBarProps {
  value?: string
  onChange?: (value: string) => void
  onSearch?: (value: string) => void
  className?: string
  placeholder?: string
  showSuggestions?: boolean
}

export function SearchBar({
  value,
  onChange,
  onSearch,
  className,
  placeholder = "Search cities, places, or events...",
  showSuggestions = true,
}: SearchBarProps) {
  const [query, setQuery] = useState(value || "")
  const [isOpen, setIsOpen] = useState(false)
  const [filteredSuggestions, setFilteredSuggestions] = useState<SearchSuggestion[]>([])
  const wrapperRef = useRef<HTMLDivElement>(null)

  useEffect(() => {
    if (query.length > 0) {
      const filtered = suggestions.filter(
        (s) =>
          s.name.toLowerCase().includes(query.toLowerCase()) || s.location?.toLowerCase().includes(query.toLowerCase()),
      )
      setFilteredSuggestions(filtered)
    } else {
      setFilteredSuggestions([])
    }
  }, [query])

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (wrapperRef.current && !wrapperRef.current.contains(event.target as Node)) {
        setIsOpen(false)
      }
    }
    document.addEventListener("mousedown", handleClickOutside)
    return () => document.removeEventListener("mousedown", handleClickOutside)
  }, [])

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const newValue = e.target.value
    setQuery(newValue)
    onChange?.(newValue)
  }

  const handleSelect = (value: string) => {
    setQuery(value)
    onChange?.(value)
    onSearch?.(value)
    setIsOpen(false)
  }

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === "Enter") {
      onSearch?.(query)
      setIsOpen(false)
    }
  }

  const getTypeIcon = (type: SearchSuggestion["type"]) => {
    switch (type) {
      case "destination":
        return "🌍"
      case "food":
        return "🍽️"
      case "event":
        return "🎉"
      case "hotel":
        return "🏨"
      default:
        return "📍"
    }
  }

  return (
    <div ref={wrapperRef} className={cn("relative w-full", className)}>
      <div className="relative">
        <Search className="absolute left-4 top-1/2 h-5 w-5 -translate-y-1/2 text-muted-foreground" />
        <Input
          type="search"
          placeholder={placeholder}
          value={query}
          onChange={handleChange}
          onFocus={() => showSuggestions && setIsOpen(true)}
          onKeyDown={handleKeyDown}
          className="h-12 pl-12 pr-4 text-base bg-background"
        />
      </div>

      {showSuggestions && isOpen && (
        <div className="absolute top-full left-0 right-0 z-50 mt-2 rounded-lg border bg-popover shadow-lg">
          {query.length > 0 && filteredSuggestions.length > 0 ? (
            <div className="p-2">
              <p className="px-3 py-2 text-xs font-medium text-muted-foreground uppercase tracking-wide">Results</p>
              {filteredSuggestions.map((suggestion) => (
                <button
                  key={suggestion.id}
                  onClick={() => handleSelect(suggestion.name)}
                  className="flex w-full items-center gap-3 rounded-md px-3 py-2 text-left hover:bg-accent transition-colors"
                >
                  <span className="text-lg">{getTypeIcon(suggestion.type)}</span>
                  <div className="flex-1 min-w-0">
                    <p className="font-medium truncate">{suggestion.name}</p>
                    {suggestion.location && (
                      <p className="text-sm text-muted-foreground truncate">{suggestion.location}</p>
                    )}
                  </div>
                </button>
              ))}
            </div>
          ) : query.length > 0 ? (
            <div className="p-8 text-center">
              <Search className="h-10 w-10 mx-auto text-muted-foreground/50 mb-3" />
              <p className="text-muted-foreground">No results found for "{query}"</p>
              <p className="text-sm text-muted-foreground/70">Try a different search term</p>
            </div>
          ) : (
            <div className="p-2">
              {recentSearches.length > 0 && (
                <div className="mb-2">
                  <p className="px-3 py-2 text-xs font-medium text-muted-foreground uppercase tracking-wide flex items-center gap-2">
                    <Clock className="h-3 w-3" /> Recent
                  </p>
                  {recentSearches.map((search) => (
                    <button
                      key={search}
                      onClick={() => handleSelect(search)}
                      className="flex w-full items-center gap-3 rounded-md px-3 py-2 text-left hover:bg-accent transition-colors"
                    >
                      <MapPin className="h-4 w-4 text-muted-foreground" />
                      <span>{search}</span>
                    </button>
                  ))}
                </div>
              )}

              <div>
                <p className="px-3 py-2 text-xs font-medium text-muted-foreground uppercase tracking-wide flex items-center gap-2">
                  <TrendingUp className="h-3 w-3" /> Trending
                </p>
                {trendingSearches.map((search) => (
                  <button
                    key={search}
                    onClick={() => handleSelect(search)}
                    className="flex w-full items-center gap-3 rounded-md px-3 py-2 text-left hover:bg-accent transition-colors"
                  >
                    <TrendingUp className="h-4 w-4 text-primary" />
                    <span>{search}</span>
                  </button>
                ))}
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  )
}
